RockCommerce.component("rcvariation",{minoptions:0,maxoptions:1,init(){RockCommerce.addComponent(this);this.minoptions=parseInt(this.$rcattr("rc-minoptions"));this.maxoptions=parseInt(this.$rcattr("rc-maxoptions"))},disableAll(){this.options.forEach((option)=>{option.disable(!0)})},get options(){return Array.from(this.$el.querySelectorAll("[x-data=rcvariationoption]")).map((el)=>RockCommerce.getComponent(el))},numSelected(){return this.$el.querySelectorAll("[x-data=rcvariationoption].rc-active").length},})